#!/usr/bin/env bash
# Generated by @navori/plugin-tgrep. The single entry point for content search:
# it picks the engine (tgrep → rg → grep), keeps the caller's exit-code contract
# (0 = match, 1 = no match) intact on all three paths, and never writes inside
# the repo.
#
# Why the choice lives HERE and not in doctrine: SessionStart hooks do not run
# for subagents, so "is tgrep installed?" cannot be answered from session
# context — researcher/implementer/reviewer would each have to guess. An `if` in
# bash gives the same answer in every agent, every mode and every machine.
#
# Usage: bash .claude/scripts/tgrep-search.sh <search args…>
# Args are passed VERBATIM to the engine; tgrep's flag surface is ripgrep's, so
# the same call works on both. Only `--index-path` is added, on the tgrep path.

set -euo pipefail

INSTALL_HINT="brew install tgrep"

# ── Flag admission (#717 C1) ──────────────────────────────────────────────────
#
# This wrapper is ALLOW-LISTED (`Bash(bash .claude/scripts/tgrep-search.sh *)`),
# so it runs with no permission prompt and no classifier round-trip, in every
# mode. That is the point of it — and it means its argv is a privileged
# surface: whatever this script hands an engine, it hands it unprompted.
#
# ripgrep can execute caller-supplied commands. `--pre CMD` runs CMD once per
# file; `--hostname-bin CMD` runs CMD too. The harness's own doctrine already
# says why `rg` is not pre-approved — "`rg --pre <cmd>` runs an arbitrary
# command per file" — and until this gate, the allow-listed wrapper was exactly
# that surface one level of indirection later: with no tgrep installed the
# fallback is `exec rg "$@"`, verbatim. Verified end to end: `rg --pre` executes,
# and the wrapper passed `--pre` straight through.
#
# ALLOWLIST, not a denylist of the executing flags. A denylist has to be right
# about every flag ripgrep adds later; this fails toward refusing, which is the
# correct direction for a surface that runs without a prompt. The cost of that
# choice is a false block, and a false block teaches the caller to route around
# the wrapper — so the set is not invented here: it is the portable subset the
# tgrep rung documents, plus the flags it explicitly calls "avoid" (legal, just
# slower), plus the ones the grep translation below already enumerates.
# `flag-doctrine.test.ts` reads that prose and fails if the two drift.
#
# Refusal is exit 2 — "nothing was searched", the contract's third code — and
# never exit 1, which would read as "no match": a false negative is the one
# outcome this wrapper exists to prevent.
SAFE_SHORT_FLAGS="iIlcnFwegABCmohvxsSatTuzrEfL"
SAFE_LONG_FLAGS="
ignore-case case-sensitive smart-case fixed-strings word-regexp line-regexp
files-with-matches files-without-match count count-matches line-number
no-line-number only-matching invert-match no-filename with-filename heading
no-heading column byte-offset regexp glob iglob type type-not type-list
type-add max-count after-context before-context context file replace
encoding engine color colors sort sortr hidden text no-ignore no-ignore-vcs
no-ignore-parent no-ignore-global no-ignore-dot no-ignore-files unrestricted
follow max-filesize max-depth maxdepth regex-size-limit dfa-size-limit
multiline multiline-dotall crlf null null-data trim search-zip
ignore-file ignore-file-case-insensitive no-max-filesize threads mmap no-mmap
binary no-config one-file-system stats quiet no-messages
index-path no-index
"

reject_flag() {
  echo "✗ tgrep-search: '$1' is not in this wrapper's supported flag set — nothing was searched." >&2
  echo "  The wrapper runs allow-listed (no prompt), so it only forwards flags that cannot make" >&2
  echo "  an engine execute a command. \`--pre\` and \`--hostname-bin\` are refused by design." >&2
  echo "  Supported: the portable subset (-i -l -c -n -F -w -e -g -A/-B/-C -m) plus --hidden," >&2
  echo "  --no-ignore*, -a and -t. For anything else use the native Grep tool." >&2
  exit 2
}

check_long_flag() {
  # `--flag=value` and `--flag` alike: only the NAME is admitted here.
  navori_flag="${1#--}"
  navori_flag="${navori_flag%%=*}"
  case "
$SAFE_LONG_FLAGS" in
    *"
$navori_flag "* | *" $navori_flag "* | *" $navori_flag
"*) return 0 ;;
  esac
  reject_flag "--$navori_flag"
}

check_short_flags() {
  # Bundled shorts (`-in`, `-uuu`, `-A3`) are admitted character by character;
  # a digit is a value glued to the flag before it, never a flag itself.
  navori_bundle="${1#-}"
  while [ -n "$navori_bundle" ]; do
    navori_char="${navori_bundle%"${navori_bundle#?}"}"
    navori_bundle="${navori_bundle#?}"
    case "$navori_char" in
      [0-9]) continue ;;
    esac
    case "$SAFE_SHORT_FLAGS" in
      *"$navori_char"*) ;;
      *) reject_flag "-$navori_char" ;;
    esac
  done
}

navori_end_of_flags=0
for navori_arg in "$@"; do
  [ "$navori_end_of_flags" -eq 0 ] || break
  case "$navori_arg" in
    --) navori_end_of_flags=1 ;;
    --*) check_long_flag "$navori_arg" ;;
    -) ;;
    -*) check_short_flags "$navori_arg" ;;
  esac
done

# The tree to index. tgrep indexes a directory, and the index has to be keyed to
# the same tree from any cwd inside it — hence the repo root, not $PWD. Outside
# a git repo the cwd IS the tree. An agent worktree resolves to itself and gets
# its own index, which is correct by construction: it indexes what that tree sees.
root="$(git rev-parse --show-toplevel 2>/dev/null || true)"
[ -n "$root" ] || root="$PWD"

# Cache key = hash of the absolute root, so a repo path with spaces (or any
# other character) never reaches the cache's own filesystem paths.
cache_key() {
  if command -v shasum >/dev/null 2>&1; then
    printf '%s' "$root" | shasum -a 256 | cut -c1-16
  elif command -v sha256sum >/dev/null 2>&1; then
    printf '%s' "$root" | sha256sum | cut -c1-16
  else
    # No hasher on this machine: a slug still separates repos from each other,
    # it just stops being collision-proof.
    printf '%s' "$root" | tr -c 'A-Za-z0-9' '-' | tail -c 40
  fi
}

# Outside the repo on purpose: tgrep's default is `.tgrep/` INSIDE the working
# tree, which would need a .gitignore entry in every repo navori renders into.
index_dir="${XDG_CACHE_HOME:-$HOME/.cache}/navori/tgrep/$(cache_key)"

if command -v tgrep >/dev/null 2>&1; then
  # Reindex before EVERY search. A stale index makes tgrep exit 1 with no
  # warning — a silent false negative, indistinguishable from "no match" — for
  # content added to an indexed file and for files created after the build. A
  # full rebuild measured 0.07s on the largest repo in the fleet (793 text
  # files), so the correct thing here is also the cheap one.
  indexed=1
  mkdir -p "$index_dir" 2>/dev/null || indexed=0
  if [ "$indexed" -eq 1 ]; then
    tgrep index "$root" --index-path "$index_dir" >/dev/null 2>&1 || indexed=0
  fi

  # NOT named `status`: that identifier is read-only in zsh (it mirrors `$?`),
  # and the assignment aborts the script there. The hooks in this harness run
  # under whatever shell the host wires in, so bash-only names are a real bug.
  search_status=0
  if [ "$indexed" -eq 1 ]; then
    tgrep --index-path "$index_dir" "$@" || search_status=$?
    # 0 = match, 1 = no match. Anything else is the index failing us (corrupt,
    # or half-written by a parallel session): redo the search WITHOUT it rather
    # than hand back an answer we can't stand behind.
    if [ "$search_status" -gt 1 ]; then
      search_status=0
      tgrep --no-index "$@" || search_status=$?
    fi
  else
    # No usable index (cache not writable, build failed): a full scan is slower
    # and correct. Never a possibly-stale index.
    tgrep --no-index "$@" || search_status=$?
  fi
  exit "$search_status"
fi

if command -v rg >/dev/null 2>&1; then
  echo "⊘ tgrep not installed — searching with rg (no trigram index, slower). Install: $INSTALL_HINT" >&2
  exec rg "$@"
fi

# Last resort. grep does not share ripgrep's flag surface, so only the
# positional arguments (the pattern and the paths) survive the translation;
# `-e PATTERN` is honoured because the doctrine lists it in the safe subset.
pattern=""
paths=()
dropped=0
expect_pattern=0
skip_value=0
for arg in "$@"; do
  if [ "$expect_pattern" -eq 1 ]; then
    pattern="$arg"
    expect_pattern=0
    continue
  fi
  # A flag's VALUE is neither the pattern nor a path. Missing this turns
  # `-g '*.ts' foo .` into a search for `*.ts` inside a path called `foo`.
  if [ "$skip_value" -eq 1 ]; then
    skip_value=0
    continue
  fi
  case "$arg" in
    -e | --regexp) expect_pattern=1 ;;
    --regexp=*) pattern="${arg#--regexp=}" ;;
    -g | -t | -T | -m | -A | -B | -C | -f | -r | -E | --glob | --iglob | --type | \
      --type-not | --max-count | --after-context | --before-context | --context | \
      --file | --replace | --encoding | --engine | --color | --max-filesize | \
      --index-path | --regex-size-limit | --dfa-size-limit)
      dropped=$((dropped + 1))
      skip_value=1
      ;;
    -*) dropped=$((dropped + 1)) ;;
    *)
      if [ -z "$pattern" ]; then pattern="$arg"; else paths+=("$arg"); fi
      ;;
  esac
done

dropped_note=""
[ "$dropped" -eq 0 ] || dropped_note=" ($dropped flag(s) grep cannot take were dropped)"
echo "⊘ neither tgrep nor rg installed — searching with grep -rn, the slowest path${dropped_note}. Install: $INSTALL_HINT" >&2

if [ -z "$pattern" ]; then
  echo "✗ tgrep-search: no search pattern in the arguments — nothing was searched" >&2
  exit 2
fi
[ ${#paths[@]} -gt 0 ] || paths=(".")

# `search_status`, not `status`: read-only in zsh (see the tgrep path above).
search_status=0
grep -rn -e "$pattern" -- "${paths[@]}" || search_status=$?
exit "$search_status"
